```json
{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_deployment_name AS dep, count(*) AS n, round(avg(value),2) AS avg_v, round(min(value),2) AS mn, round(max(value),2) AS mx FROM abnormal_metrics_sum WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='user' GROUP BY ALL",
          "claim": "The user deployment reports 0 available pods across the entire abnormal window; it was 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n FROM abnormal_traces WHERE service_name='user' GROUP BY ALL",
          "claim": "The user service emitted only one span in the abnormal window, versus 290 in the normal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration)/1e6,3) AS avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' GROUP BY ALL",
          "claim": "All 355 frontend calls to user.User/CheckUser return Error in about 0.01 ms, a fast fail with no user response."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.span_name AS server_span, s.attr_http_response_status_code AS sc, c.span_name AS child_span, c.attr_status_code AS child_status, count(*) AS n FROM abnormal_traces s JOIN abnormal_traces c ON s.trace_id=c.trace_id AND c.parent_span_id=s.span_id WHERE s.service_name='frontend' AND s.attr_span_kind='Server' AND s.attr_status_code='Error' GROUP BY ALL ORDER BY n DESC",
          "claim": "Every frontend HTTP 500 (/cinema, /museums, /restaurants, /reservation, /user) has a failed user.User/CheckUser child span."
        }
      ]
    }
  ]
}
```

